<?php
declare(strict_types=1);
namespace DigiForge\PortalAccess;
final class Panel {
 private static function shop():string{$s=$_GET['df_shop']??'personalized_pod';return is_string($s)&&\DigiForge\Security\ShopAccessPolicy::validShop($s)?$s:'';}
 private static function form(string $action,string $shop):string{return '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field($action,'_wpnonce',true,false).'<input type="hidden" name="action" value="'.esc_attr($action).'"><input type="hidden" name="shop" value="'.esc_attr($shop).'"><input type="hidden" name="request_id" value="'.esc_attr(wp_generate_uuid4()).'">';}
 private static function confirm():string{return '<label><input name="confirm" value="CONFIRM_DIGIFORGE_ONLY" type="checkbox" required>I confirm this DigiForge-only change.</label>';}
 private static function fields(string $role='Viewer',array $caps=[]):string{$h='<label>DigiForge role<select name="role">';foreach(['Admin','Operator','Viewer'] as $r)$h.='<option '.selected($role,$r,false).'>'.esc_html($r).'</option>';$h.='</select></label><input type="hidden" name="modules_present" value="1"><fieldset><legend>Exact modules (no automatic access)</legend>';foreach(Policy::MODULES as $m=>$c)$h.='<label><input type="checkbox" name="modules[]" value="'.esc_attr($m).'" '.checked(in_array($c,$caps,true),true,false).'>'.esc_html($m).'</label>';return $h.'</fieldset>';}
 public static function render():string {
  $shop=self::shop();if(Owner::require($shop)!==true)return '<section class="df-access-card"><h1>User management</h1><p role="alert">Current independently signed Primary Owner enrollment is required for this shop. WordPress administrator status is insufficient.</p></section>';
  $h='<section class="df-access-card"><h1>Owner dashboard and user management</h1><p>Shop: '.esc_html($shop).'. Changes affect DigiForge only. WordPress accounts, passwords, roles and unrelated sessions are preserved.</p><p>Viewer permits approved reads only. Existing WordPress capabilities and current signed shop grants remain required. No email is sent.</p>';
  $h.='<nav aria-label="User management shop scope">';foreach(['digital'=>'Digital Products','personalized_pod'=>'Personalized POD','standard_pod'=>'Standard POD','jewelry'=>'Personalized Jewelry'] as $key=>$label){if(Owner::require($key)===true)$h.='<a href="'.esc_url(add_query_arg(['df_view'=>'users','df_shop'=>$key],home_url('/'))).'"'.($key===$shop?' aria-current="page"':'').'>'.esc_html($label).'</a> ';}$h.='</nav><p>Administrative shop selection does not enable inactive workflows.</p>';
  if(isset($_GET['df_result']))$h.='<p role="status">'.($_GET['df_result']==='recorded'?'DigiForge change recorded.':'Change blocked. Refresh current authority and revision.').'</p>';
  $h.='<h2>Invite an existing WordPress account</h2>'.self::form('digiforge_portal_users',$shop).'<input type="hidden" name="operation" value="INVITE"><label>Existing account email<input type="email" name="email" required></label>'.self::fields().'<label>Invitation lifetime<select name="lifetime"><option value="600">10 minutes</option><option value="1800">30 minutes</option></select></label>'.self::confirm().'<button>Prepare private invitation</button></form><h2>Assigned users and permission history</h2>';
  global $wpdb;$wpdb->last_error='';$keys=$wpdb->get_col($wpdb->prepare("SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE %s ORDER BY option_id DESC LIMIT 101",$wpdb->esc_like('digiforge_portal_profile_').'%'));if($wpdb->last_error!==''||!is_array($keys))return $h.'<p>Assignment evidence unavailable; management blocked.</p></section>';
  foreach(array_slice($keys,0,100) as $key){if(!preg_match('/^digiforge_portal_profile_([1-9][0-9]*)$/D',$key,$m))continue;$id=(int)$m[1];$s=Store::read($id);if(is_wp_error($s)){return $h.'<p>Profile integrity failed; no changes were made.</p></section>';}if($s===null||(!isset($s['shops'][$shop])&&!in_array($shop,$s['managed_shops']??[],true)))continue;$u=get_userdata($id);$h.='<article><h3>'.esc_html($u?$u->display_name:'Account unavailable').' — #'.$id.'</h3><p>'.esc_html($s['role']).' / '.($s['enabled']?'enabled':'disabled or pending').' / revision '.$s['revision'].'</p><p>'.esc_html(implode(', ',$s['shops'][$shop]??[])).'</p>';
   if(!in_array($s['role'],['Primary Owner',GlobalOwnerAuthority::ROLE],true))$h.=self::form('digiforge_portal_users',$shop).'<input type="hidden" name="operation" value="CHANGE"><input type="hidden" name="subject_id" value="'.$id.'"><input type="hidden" name="revision" value="'.$s['revision'].'">'.self::fields($s['role'],$s['shops'][$shop]??[]).'<label>Access state<select name="enabled"><option value="0" '.selected($s['enabled'],false,false).'>Disable / revoke DigiForge access</option><option value="1" '.selected($s['enabled'],true,false).'>Enable DigiForge access</option></select></label>'.self::confirm().'<button>Confirm scoped change</button></form>';
   $rows=$wpdb->get_col($wpdb->prepare("SELECT context FROM ".\DigiForge\Database\Tables::audit_log()." WHERE object_type='portal_access_profile' AND object_id=%s AND event_type='portal_profile_changed' ORDER BY id DESC LIMIT 20",(string)$id));$h.='<details><summary>Permission history (latest 20)</summary><ul>';foreach($rows?:[] as $raw){$e=json_decode($raw,true);$scope=$e['state']['shops'][$shop]??null;if(!is_array($scope))continue;$h.='<li>Revision '.(int)$e['revision'].' by #'.(int)$e['actor_id'].' — '.esc_html($e['state']['role']).' — '.($e['state']['enabled']?'enabled':'disabled/pending').' — '.esc_html(implode(', ',$scope)).'</li>';}$h.='</ul></details></article>';
  }if(count($keys)>100)$h.='<p>Latest 100 profiles shown. Do not infer that this is a complete site inventory.</p>';return $h.'</section>';
 }
 public static function bootstrap():string{return OwnerBootstrap::render();}
 public static function invitation():string{return '<section class="df-access-card"><h1>Accept DigiForge invitation</h1><p>You must be signed into the intended existing WordPress account. Acceptance grants only the reviewed DigiForge scope; it does not change WordPress roles.</p>'.self::form('digiforge_portal_invitation_accept','').'<label>Private invitation code<input name="invite" id="df-invitation-code" autocomplete="off" maxlength="64" required></label><button>Accept this invitation</button></form></section>';}
 public static function process(string $action,array $p):array|\WP_Error {
  if(($p['confirm']??null)!=='CONFIRM_DIGIFORGE_ONLY'||!is_string($p['shop']??null)||!\DigiForge\Security\ShopAccessPolicy::validShop($p['shop'])||!is_string($p['request_id']??null))return Policy::error('confirmation');$shop=$p['shop'];
  if($action==='digiforge_portal_owner_enroll')return Policy::error('global_bootstrap_required');
  if(Owner::require($shop)!==true||!is_string($p['role']??null))return Policy::error('owner');
  // Unchecked HTML checkboxes omit modules entirely. Only an explicit change
  // form marker can represent that omission as a deliberate empty selection.
  if(!array_key_exists('modules',$p)&&($p['operation']??null)==='CHANGE'&&($p['modules_present']??null)==='1')$p['modules']=[];
  if(!is_array($p['modules']??null))return Policy::error('typed');
  if(($p['operation']??null)==='INVITE'){$u=is_string($p['email']??null)?get_user_by('email',$p['email']):false;$ttl=$p['lifetime']??null;if(!$u||!in_array($ttl,['600','1800'],true))return Policy::error('existing_account');return Invitations::create($u->ID,$p['role'],$shop,$p['modules'],time()+(int)$ttl,$p['request_id']);}
  if(($p['operation']??null)!=='CHANGE'||!is_string($p['subject_id']??null)||!ctype_digit($p['subject_id'])||!is_string($p['revision']??null)||!ctype_digit($p['revision'])||!in_array($p['enabled']??null,['0','1'],true))return Policy::error('typed');
  $id=(int)$p['subject_id'];$old=Store::read($id);if(is_wp_error($old))return $old;$shops=[];foreach($old['shops']??[] as $s=>$caps){$shops[$s]=[];foreach(Policy::MODULES as $m=>$cap)if(in_array($cap,$caps,true))$shops[$s][]=$m;}$shops[$shop]=$p['modules'];return Store::change($id,$p['role'],$shops,$p['enabled']==='1',(int)$p['revision'],$p['request_id']);
 }
}
